def smallest_change(arr):
    n = len(arr)
    dp = [[0] * n for _ in range(n)]

    for gap in range(1, n):
        for i in range(n - gap):
            j = i + gap
            if arr[i] == arr[j]:
                dp[i][j] = dp[i + 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i][j - 1], dp[i + 1][j])

    return dp[0][n - 1]

